// Remember when each job last pinged. Runs on every ping.
const job = String($input.first().json.query?.job ?? '');
if (!/^[A-Za-z0-9_-]{1,64}$/.test(job)) {
  return [{ json: { ok: false, reason: 'job must be 1-64 chars of A-Z a-z 0-9 _ -' } }];
}
const sd = $getWorkflowStaticData('global');
sd.lastPing = sd.lastPing || {};
sd.alerted = sd.alerted || {};
sd.lastPing[job] = new Date().toISOString();
delete sd.alerted[job]; // it is alive again, so it may alert again later
return [{ json: { ok: true, job, at: sd.lastPing[job] } }];

// EDIT THIS: job name -> the longest silence you accept, in hours.
const EXPECT = {
  'job-a': 0.01,
  'job-b': 0.01,
};

const sd = $getWorkflowStaticData('global');
sd.lastPing = sd.lastPing || {};
sd.alerted = sd.alerted || {};
sd.baseline = sd.baseline || {};
const now = Date.now();
const late = [];
for (const [job, maxHours] of Object.entries(EXPECT)) {
  // A job that has never pinged is measured from the first time this check saw it,
  // so installing the workflow does not alert immediately.
  if (!sd.lastPing[job] && !sd.baseline[job]) sd.baseline[job] = new Date(now).toISOString();
  const since = new Date(sd.lastPing[job] ?? sd.baseline[job]).getTime();
  const hours = (now - since) / 36e5;
  if (hours > maxHours && !sd.alerted[job]) {
    sd.alerted[job] = new Date(now).toISOString(); // one alert per outage
    late.push(`${job}: ${sd.lastPing[job] ? 'last ping ' + hours.toFixed(1) + ' h ago' : 'no ping since monitoring started ' + hours.toFixed(1) + ' h ago'} (limit ${maxHours} h)`);
  }
}
if (!late.length) return [];
return [{ json: { subject: `Heartbeat missing: ${late.length} job(s)`, text: late.join('\n') + '\n\nIf the job is fine, check that its ping URL is still called at the end of the job.' } }];
